 const frame=new THREE.Group();frame.name='UnitV-M12 '+id+' fixed switch package';frame.position.set(sign*9.1,-14.2,-2.7);host.body.add(frame);const base=box(frame,[2.35,3.1,.55],[0,0,.275],dark(),'UnitV-M12 '+id+' actual closed switch base on PCB'),body=box(frame,[2.3,2.6,1.3],[0,0,1.2],dark(),'UnitV-M12 '+id+' fixed side switch body'),lid=box(frame,[2.4,2.7,.15],[0,0,1.925],metal(),'UnitV-M12 '+id+' fixed retention lid'),terminals=[];
